DROP TABLE IF EXISTS `documents`;
CREATE TABLE `documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` tinyint(3) unsigned NOT NULL,
  `type` enum('outgoing','incoming','internal') NOT NULL DEFAULT 'outgoing',
  `document_number` varchar(100) NOT NULL,
  `document_date` date NOT NULL,
  `recipient` varchar(255) NOT NULL,
  `recipient_id` int(10) unsigned DEFAULT NULL,
  `subject` varchar(500) NOT NULL,
  `uploaded_by` int(10) unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `registry_number` varchar(100) GENERATED ALWAYS AS (if((`type` = 'internal'),NULL,`document_number`)) STORED,
  PRIMARY KEY (`id`),
  KEY `organization_id` (`organization_id`),
  KEY `recipient_id` (`recipient_id`),
  KEY `uploaded_by` (`uploaded_by`),
  CONSTRAINT `documents_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `documents_ibfk_2` FOREIGN KEY (`recipient_id`) REFERENCES `recipients` (`id`),
  CONSTRAINT `documents_ibfk_3` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4;
